}

package com.seedreminder;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("seedreminder")
public interface SeedReminderConfig extends Config
{
	@ConfigSection(
		name = "Matching Rules",
		description = "How seeds are matched to the Seed Vault and Bank",
		position = 0
	)
	String rulesSection = "rules";

	@ConfigSection(
		name = "Display Options",
		description = "Visual appearance and placement of markers",
		position = 1
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "vaultMode",
		name = "Vault Matching Rule",
		description = "Which seeds should display the Seed Vault marker",
		position = 0,
		section = rulesSection
	)
	default VaultTrackMode vaultMode()
	{
		return VaultTrackMode.STORED_IN_VAULT;
	}

	@ConfigItem(
		keyName = "showVaultIcon",
		name = "Show Vault Marker",
		description = "Display a marker on seeds that belong in the Seed Vault",
		position = 1,
		section = displaySection
	)
	default boolean showVaultIcon()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBankIcon",
		name = "Show Bank Marker",
		description = "Display a marker on seeds that are stored in your Bank",
		position = 2,
		section = displaySection
	)
	default boolean showBankIcon()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showOnInventory",
		name = "Show in Inventory",
		description = "Display markers on seeds in your inventory",
		position = 3,
		section = displaySection
	)
	default boolean showOnInventory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOnBank",
		name = "Show in Bank",
		description = "Display markers on seeds inside the bank interface",
		position = 4,
		section = displaySection
	)
	default boolean showOnBank()
	{
		return true;
	}

	@ConfigItem(
		keyName = "markerStyle",
		name = "Marker Style",
		description = "Visual marker style (icon, badge letter, outline, etc.)",
		position = 5,
		section = displaySection
	)
	default MarkerStyle markerStyle()
	{
		return MarkerStyle.ICON;
	}

	@ConfigItem(
		keyName = "iconPosition",
		name = "Marker Position",
		description = "Corner of the item slot to place the marker",
		position = 6,
		section = displaySection
	)
	default IconPosition iconPosition()
	{
		return IconPosition.TOP_RIGHT;
	}

	@ConfigItem(
		keyName = "showTooltips",
		name = "Show Tooltips",
		description = "Display Seed Vault and Bank quantity details when hovering over seeds",
		position = 7,
		section = displaySection
	)
	default boolean showTooltips()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "vaultColor",
		name = "Vault Marker Color",
		description = "Color used for badge and outline markers for Seed Vault items",
		position = 8,
		section = displaySection
	)
	default Color vaultColor()
	{
		return new Color(46, 125, 50, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "bankColor",
		name = "Bank Marker Color",
		description = "Color used for badge and outline markers for Bank items",
		position = 9,
		section = displaySection
	)
	default Color bankColor()
	{
		return new Color(255, 193, 7, 220);
	}
}

package com.seedreminder;

import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

@Slf4j
@Singleton
public class SeedReminderOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final ItemManager itemManager;
	private final SeedReminderPlugin plugin;
	private final SeedReminderConfig config;
	private final TooltipManager tooltipManager;

	private final BufferedImage vaultIcon;
	private final BufferedImage bankIcon;

	@Inject
	public SeedReminderOverlay(
		Client client,
		ItemManager itemManager,
		SeedReminderPlugin plugin,
		SeedReminderConfig config,
		TooltipManager tooltipManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.plugin = plugin;
		this.config = config;
		this.tooltipManager = tooltipManager;

		showOnInventory();
		showOnBank();
		showOnInterfaces(InterfaceID.SEED_VAULT);

		BufferedImage vIcon = null;
		BufferedImage bIcon = null;
		try
		{
			vIcon = ImageUtil.loadImageResource(SeedReminderPlugin.class, "vault_icon.png");
			bIcon = ImageUtil.loadImageResource(SeedReminderPlugin.class, "bank_icon.png");
		}
		catch (Exception e)
		{
			log.debug("Could not load icon images", e);
		}
		this.vaultIcon = vIcon;
		this.bankIcon = bIcon;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		int canonicalId = itemManager.canonicalize(itemId);
		if (!FarmingSeeds.isSeedOrSapling(canonicalId, itemManager, plugin))
		{
			return;
		}

		if (widgetItem == null || widgetItem.getWidget() == null)
		{
			return;
		}

		int interfaceId = WidgetUtil.componentToInterface(widgetItem.getWidget().getId());
		if (interfaceId == InterfaceID.BANKMAIN)
		{
			if (!config.showOnBank())
			{
				return;
			}
		}
		else
		{
			if (!config.showOnInventory())
			{
				return;
			}
		}

		boolean isVaultSeed = plugin.isSeedForVault(canonicalId);
		boolean isBankSeed = plugin.isSeedForBank(canonicalId);
		boolean showVault = config.showVaultIcon() && isVaultSeed;
		boolean showBank = config.showBankIcon() && isBankSeed && !isVaultSeed;

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		if (config.showTooltips())
		{
			Point mousePos = client.getMouseCanvasPosition();
			if (mousePos != null && bounds.contains(mousePos.getX(), mousePos.getY()))
			{
				renderTooltip(canonicalId, showVault, isBankSeed);
			}
		}

		if (showVault)
		{
			drawMarker(graphics, bounds, vaultIcon, config.vaultColor(), "V");
		}
		else if (showBank)
		{
			drawMarker(graphics, bounds, bankIcon, config.bankColor(), "B");
		}
	}

	private void renderTooltip(int canonicalId, boolean isVaultSeed, boolean isBankSeed)
	{
		ItemComposition comp = itemManager.getItemComposition(canonicalId);
		String name = comp != null ? comp.getName() : "Seed";
		StringBuilder sb = new StringBuilder();
		sb.append(ColorUtil.wrapWithColorTag(name, Color.WHITE)).append("</br>");

		int vaultQty = plugin.getVaultQuantity(canonicalId);
		if (plugin.isVaultScanned())
		{
			if (vaultQty > 0)
			{
				sb.append("Seed Vault: ").append(ColorUtil.wrapWithColorTag(vaultQty + " stored", Color.GREEN));
			}
			else
			{
				sb.append("Seed Vault: ").append(ColorUtil.wrapWithColorTag("0 stored", Color.GRAY));
			}
		}
		else
		{
			sb.append("Seed Vault: ").append(ColorUtil.wrapWithColorTag("Not yet opened", Color.ORANGE));
		}
		sb.append("</br>");

		int bankQty = plugin.getBankQuantity(canonicalId);
		if (plugin.isBankScanned())
		{
			if (bankQty > 0)
			{
				sb.append("Bank: ").append(ColorUtil.wrapWithColorTag(bankQty + " stored", Color.YELLOW));
			}
			else
			{
				sb.append("Bank: ").append(ColorUtil.wrapWithColorTag("0 stored", Color.GRAY));
			}
		}
		else
		{
			sb.append("Bank: ").append(ColorUtil.wrapWithColorTag("Not yet opened", Color.ORANGE));
		}
		sb.append("</br>");

		if (isVaultSeed)
		{
			sb.append("Target: ").append(ColorUtil.wrapWithColorTag("Seed Vault", Color.GREEN));
		}
		else if (isBankSeed)
		{
			sb.append("Target: ").append(ColorUtil.wrapWithColorTag("Bank", Color.YELLOW));
		}

		tooltipManager.add(new Tooltip(sb.toString()));
	}

	private void drawMarker(Graphics2D graphics, Rectangle bounds, BufferedImage icon, Color color, String badgeLetter)
	{
		MarkerStyle style = config.markerStyle();
		if (style == MarkerStyle.OUTLINE || style == MarkerStyle.ICON_AND_OUTLINE)
		{
			graphics.setColor(color);
			graphics.drawRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1);
		}

		if (style == MarkerStyle.ICON || style == MarkerStyle.ICON_AND_OUTLINE)
		{
			if (icon != null)
			{
				Point loc = getIconLocation(bounds, icon.getWidth(), icon.getHeight());
				graphics.drawImage(icon, loc.getX(), loc.getY(), null);
			}
			else
			{
				drawBadge(graphics, bounds, color, badgeLetter);
			}
		}
		else if (style == MarkerStyle.BADGE)
		{
			drawBadge(graphics, bounds, color, badgeLetter);
		}
	}

	private void drawBadge(Graphics2D graphics, Rectangle bounds, Color color, String letter)
	{
		int badgeSize = 12;
		Point loc = getIconLocation(bounds, badgeSize, badgeSize);
		int x = loc.getX();
		int y = loc.getY();

		graphics.setColor(new Color(0, 0, 0, 180));
		graphics.fillRoundRect(x, y, badgeSize, badgeSize, 3, 3);

		graphics.setColor(color);
		graphics.fillRoundRect(x + 1, y + 1, badgeSize - 2, badgeSize - 2, 2, 2);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = graphics.getFontMetrics();
		int textX = x + (badgeSize - fm.stringWidth(letter)) / 2;
		int textY = y + ((badgeSize - fm.getHeight()) / 2) + fm.getAscent();

		graphics.setColor(Color.BLACK);
		graphics.drawString(letter, textX + 1, textY + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(letter, textX, textY);
	}

	private Point getIconLocation(Rectangle bounds, int iconWidth, int iconHeight)
	{
		int x = bounds.x;
		int y = bounds.y;
		int pad = 1;

		switch (config.iconPosition())
		{
			case TOP_LEFT:
				return new Point(x + pad, y + pad);
			case TOP_RIGHT:
				return new Point(x + bounds.width - iconWidth - pad, y + pad);
			case BOTTOM_LEFT:
				return new Point(x + pad, y + bounds.height - iconHeight - pad);
			case BOTTOM_RIGHT:
				return new Point(x + bounds.width - iconWidth - pad, y + bounds.height - iconHeight - pad);
			default:
				return new Point(x + bounds.width - iconWidth - pad, y + pad);
		}
	}
}

package com.seedreminder;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Seed Reminder",
	description = "Tracks seeds in your bank and seed vault, and shows which seeds go where",
	tags = {"seed", "vault", "bank", "farming", "reminder", "storage"}
)
public class SeedReminderPlugin extends Plugin
{
	static final String CONFIG_GROUP = "seedreminder";
	private static final String KEY_VAULT_SEEDS = "vaultSeeds";
	private static final String KEY_BANK_SEEDS = "bankSeeds";
	private static final String KEY_VAULT_SCANNED = "vaultScanned";
	private static final String KEY_BANK_SCANNED = "bankScanned";

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private SeedReminderConfig config;

	@Inject
	private SeedReminderOverlay overlay;

	private final Map<Integer, Integer> vaultSeeds = new ConcurrentHashMap<>();
	private final Map<Integer, Integer> bankSeeds = new ConcurrentHashMap<>();

	@Getter
	private boolean vaultScanned = false;

	@Getter
	private boolean bankScanned = false;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
		loadStoredData();
		log.debug("Seed Reminder started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		vaultSeeds.clear();
		bankSeeds.clear();
		vaultScanned = false;
		bankScanned = false;
		log.debug("Seed Reminder stopped!");
	}

	@Provides
	SeedReminderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SeedReminderConfig.class);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadStoredData();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadStoredData();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		ItemContainer container = event.getItemContainer();
		if (container == null)
		{
			return;
		}

		if (containerId == InventoryID.SEED_VAULT)
		{
			updateVaultSeeds(container);
		}
		else if (containerId == InventoryID.BANK)
		{
			updateBankSeeds(container);
		}
	}

	private void updateVaultSeeds(ItemContainer container)
	{
		vaultSeeds.clear();
		Item[] items = container.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0)
				{
					continue;
				}

				int canonicalId = itemManager.canonicalize(item.getId());
				vaultSeeds.merge(canonicalId, item.getQuantity(), Integer::sum);
			}
		}

		vaultScanned = true;
		saveVaultData();
		log.debug("Updated Seed Vault container: {} unique seeds tracked", vaultSeeds.size());
	}

	private void updateBankSeeds(ItemContainer container)
	{
		bankSeeds.clear();
		Item[] items = container.getItems();
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0)
				{
					continue;
				}

				int canonicalId = itemManager.canonicalize(item.getId());
				if (FarmingSeeds.isSeedOrSapling(canonicalId, itemManager, this))
				{
					bankSeeds.merge(canonicalId, item.getQuantity(), Integer::sum);
				}
			}
		}

		bankScanned = true;
		saveBankData();
		log.debug("Updated Bank container: {} unique seeds tracked", bankSeeds.size());
	}

	public boolean isSeedInVault(int canonicalId)
	{
		Integer count = vaultSeeds.get(canonicalId);
		return count != null && count > 0;
	}

	public int getVaultQuantity(int canonicalId)
	{
		return vaultSeeds.getOrDefault(canonicalId, 0);
	}

	public boolean isSeedInBank(int canonicalId)
	{
		Integer count = bankSeeds.get(canonicalId);
		return count != null && count > 0;
	}

	public int getBankQuantity(int canonicalId)
	{
		return bankSeeds.getOrDefault(canonicalId, 0);
	}

	public boolean isSeedForVault(int canonicalId)
	{
		if (!FarmingSeeds.isSeedOrSapling(canonicalId, itemManager, this))
		{
			return false;
		}

		switch (config.vaultMode())
		{
			case STORED_IN_VAULT:
				if (vaultScanned)
				{
					return isSeedInVault(canonicalId);
				}
				// If the vault has not been opened yet on this profile, fall back to marking seeds not in bank
				return !isSeedInBank(canonicalId);
			case NOT_IN_BANK:
				return !isSeedInBank(canonicalId);
			case VAULT_OR_NOT_IN_BANK:
				return isSeedInVault(canonicalId) || !isSeedInBank(canonicalId);
			case ALL_VAULT_ELIGIBLE:
				return true;
			default:
				return isSeedInVault(canonicalId);
		}
	}

	public boolean isSeedForBank(int canonicalId)
	{
		if (!FarmingSeeds.isSeedOrSapling(canonicalId, itemManager, this))
		{
			return false;
		}

		return isSeedInBank(canonicalId);
	}

	private void saveVaultData()
	{
		try
		{
			SeedStorageData data = new SeedStorageData();
			data.setSeeds(new HashMap<>(vaultSeeds));
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_VAULT_SEEDS, gson.toJson(data));
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_VAULT_SCANNED, Boolean.toString(vaultScanned));
		}
		catch (Exception e)
		{
			log.debug("Error saving vault data", e);
		}
	}

	private void saveBankData()
	{
		try
		{
			SeedStorageData data = new SeedStorageData();
			data.setSeeds(new HashMap<>(bankSeeds));
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_BANK_SEEDS, gson.toJson(data));
			configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY_BANK_SCANNED, Boolean.toString(bankScanned));
		}
		catch (Exception e)
		{
			log.debug("Error saving bank data", e);
		}
	}

	private void loadStoredData()
	{
		vaultSeeds.clear();
		bankSeeds.clear();

		try
		{
			String vaultJson = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_VAULT_SEEDS);
			if (vaultJson != null && !vaultJson.isEmpty())
			{
				SeedStorageData data = gson.fromJson(vaultJson, SeedStorageData.class);
				if (data != null && data.getSeeds() != null)
				{
					vaultSeeds.putAll(data.getSeeds());
				}
			}

			String vaultScannedStr = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_VAULT_SCANNED);
			vaultScanned = Boolean.parseBoolean(vaultScannedStr) || !vaultSeeds.isEmpty();

			String bankJson = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_BANK_SEEDS);
			if (bankJson != null && !bankJson.isEmpty())
			{
				SeedStorageData data = gson.fromJson(bankJson, SeedStorageData.class);
				if (data != null && data.getSeeds() != null)
				{
					bankSeeds.putAll(data.getSeeds());
				}
			}

			String bankScannedStr = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY_BANK_SCANNED);
			bankScanned = Boolean.parseBoolean(bankScannedStr) || !bankSeeds.isEmpty();
		}
		catch (Exception e)
		{
			log.debug("Error loading stored seed data", e);
		}
	}
}

