	NOT_IN_BANK("Not in Bank", "Marks any seed not currently in your bank as belonging in the vault"),
	VAULT_OR_NOT_IN_BANK("Vault or Not in Bank", "Marks seeds in your vault, plus any seed not in your bank"),
